import RNA, random, multiprocessing as mp
target='.....((((((((((((....))))((((....))))))))((((((((....))))((((....))))))))))))....................'
n=len(target)
def worker(seed):
    random.seed(seed)
    for _ in range(60):
        start=''.join(random.choice('ACGU') for _ in range(n))
        seq,d=RNA.inverse_fold(start,target)
        if d==0 and RNA.fold_compound(seq).mfe()[0]==target:
            return seq
    return None
if __name__=='__main__':
    found=None
    with mp.Pool(48) as p:
        for r in p.imap_unordered(worker,range(480)):
            if r:
                found=r; p.terminate(); break
    if found:
        st,en=RNA.fold_compound(found).mfe()
        print('SOLVED', found)
        print('mfe_freq', RNA.fold_compound(found).pr_structure(target))
    else:
        print('NONE')
EOF

